"""Evaluate requests against caller-supplied evidence and policy."""

import json


def _canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False)


def _superseded_ids(record):
    supersedes = record.get("supersedes", [])
    if isinstance(supersedes, str):
        return (supersedes,)
    if isinstance(supersedes, list):
        return tuple(item for item in supersedes if isinstance(item, str))
    return ()


def evaluate(request, evidence, policy):
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {"status": "unknown", "value": None, "sources": [], "unknowns": missing}

    eligible = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue
        record_conditions = record.get("conditions", {})
        if any(
            name not in record_conditions
            or _canonical(record_conditions[name]) != _canonical(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded = set()
    for record in eligible:
        source = record.get("source")
        superseded.update(source_id for source_id in _superseded_ids(record) if source_id != source)
    eligible = [record for record in eligible if record.get("source") not in superseded]

    if not eligible:
        return {"status": "unknown", "value": None, "sources": [], "unknowns": ["no matching evidence"]}

    sources = sorted({record["source"] for record in eligible})
    canonical_values = {_canonical(record.get("value")) for record in eligible}
    if len(canonical_values) != 1:
        return {"status": "conflict", "value": None, "sources": sources, "unknowns": ["source disagreement"]}

    value = eligible[0].get("value")
    return {
        "status": "unsupported" if value is False else "supported",
        "value": value,
        "sources": sources,
        "unknowns": [],
    }

